using System;using System.IO;using System.Windows;using System.Windows.Controls;using DualSteam.UI;
public partial class App {
 SettingRow PreferenceRow(string title,string detail,bool value,Action<bool> changed){var row=new SettingRow(title,detail){Margin=new Thickness(0),MinHeight=76};row.Toggle.IsChecked=value;RoutedEventHandler save=(s,e)=>{changed(row.Toggle.IsChecked==true);Preferences.Save();};row.Toggle.Checked+=save;row.Toggle.Unchecked+=save;return row;}
 WrapPanel ToolActions(params Button[] buttons){var panel=new WrapPanel();foreach(var button in buttons){button.Width=214;button.Margin=new Thickness(0,8,8,0);panel.Children.Add(button);}return panel;}
 void SaveDiagnostics(){Act(()=>{Directory.CreateDirectory(Path.Combine(Engine.Home,"Verification"));object state;try{state=Engine.Status();}catch(Exception ex){state=new{Error=ex.Message};}File.WriteAllText(Path.Combine(Engine.Home,@"Verification\diagnostics.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{Version=DualSteam.UpdateService.CurrentVersion,Native=state,Main=PerformanceSnapshot.Main(),Paths=new{Main=Engine.Current==null?Engine.DetectSteam():Engine.Current.MainSteam,Second=Engine.NativeRoot,Profile=Engine.ProfileRoot},MillenniumImported=MillenniumSharing.CanDisable}));},"Diagnostic report saved in Verification. No passwords included.");}
 FrameworkElement GeneralSettings(){
  var body=Stack();var path=Text(Engine.Current==null?"Choose a data folder when setting up Second Steam.":Engine.NativeRoot,12,"text.secondary");path.Margin=new Thickness(0,8,0,8);body.Children.Add(Group(Text("Profile storage",14,"text.primary",true),path,Text("Second Steam has a separate Windows account, login and profile. Windows also keeps system account records on the system drive.",13,"text.secondary"),ActionButton("Verify native setup",Configure)));
  body.Children.Add(Group(Text("Window and background",14,"text.primary",true),PreferenceRow("Close to tray","The window closes while the manager stays active.",Preferences.Current.TrayOnClose,v=>Preferences.Current.TrayOnClose=v),Ui.Divider(),PreferenceRow("Second Steam tray control","Show quick access to the second profile in the notification area.",Preferences.Current.SecondTray,v=>Preferences.Current.SecondTray=v),Ui.Divider(),PreferenceRow("Separate taskbar group","Keep the manager, Main Steam and Second Steam in separate groups.",Preferences.Current.SeparateTaskbar,v=>Preferences.Current.SeparateTaskbar=v)));
  body.Children.Add(Group(Text("Maintenance",14,"text.primary",true),ToolActions(ActionButton("Repair desktop shortcuts",Shortcuts),ActionButton("Reset app preferences",()=>{if(AppDialog.Show(window,"Reset appearance, sharing and background preferences? Steam logins and game files are preserved.","Reset preferences",MessageBoxButton.YesNo)==MessageBoxResult.Yes){Preferences.Current=new Preferences();Preferences.Save();Theme.Apply("Dark");File.WriteAllText(Path.Combine(Engine.Home,@"Data\theme.txt"),"Dark");ShowPage("Settings");}}),ActionButton("Save diagnostics",SaveDiagnostics))));
  body.Children.Add(Group(Text("Exit application",14,"text.primary",true),Text("Exit closes Dual Steam, the managed second client and its games. Save your game first. Main Steam remains open.",13,"text.secondary"),ActionButton("Exit Dual Steam",ExitManager)));body.Children.Add(RemovalOptions());return body;
 }
 FrameworkElement CompatibilitySettings(){var body=Stack();body.Children.Add(AddonOptions());medalStatus=Text(MedalCompatibility.Status,13,"text.secondary");medalStatus.Margin=new Thickness(0,8,0,8);body.Children.Add(Group(Text("Medal troubleshooting",14,"text.primary",true),medalStatus,Text("Optional: pause Medal's Steam lobby and friend helpers while keeping recording available. Restore reverses the change.",13,"text.secondary"),ToolActions(ActionButton("Enable compatibility",()=>Act(MedalCompatibility.Enable,"Medal compatibility enabled.")),ActionButton("Restore Steam features",()=>Act(MedalCompatibility.Restore,"Medal Steam features restored.")))));return body;}
 void LaunchWithoutMillennium(){if(!ServiceReady())return;Act(()=>{if(Engine.Current==null)throw new IOException("Set up Second Steam first.");if((Engine.Status().RootIds??new int[0]).Length>0)throw new IOException("Quit Second Steam before changing its runtime.");if(MillenniumSharing.CanDisable)MillenniumSharing.Disable();else if(File.Exists(Path.Combine(Engine.NativeRoot,@"Client\wsock32.dll")))throw new IOException("This loader was not imported by Dual Steam. Remove it with its own uninstaller before using a clean launch.");Engine.OpenSecond();},"Second Steam opened without the imported Millennium runtime.",secondCard);}
